#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# ═══════════════════════════════════════════════════════════════
# ПАТЧ: РОЖДЕНИЕ БРУТА (A06) — первый трейдер Совета Биржи
# patch_brut_birth.py · 2026-06-18
#
# Кладёт МОЗГ Брута + новый промт (три коробки) + вылеченную книгу
# Котина (сверена с Законом Дежурства v1.1).
#
# Идемпотентный: повторный запуск перезапишет файлы свежими версиями,
# сделав бэкап существующих. Маркер BRUT_ENGINE_V1 в brut_live.py.
#
# ЧТО НЕ ДЕЛАЕТ (отдельным патчем 2): не трогает кнопку ui_exchange.py.
# После этого патча Брут существует как функция — проверь руками:
#   from studio.modules.trading.brut_live import run_brut
#   r = run_brut(); print(r["narrative"]); print(r["signal"])
# (нужен поднятый MT5 и свежий прогон сенсоров — стол должен быть накрыт)
# ═══════════════════════════════════════════════════════════════

import base64
import shutil
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
TRADING = ROOT / "studio" / "modules" / "trading"
A06 = TRADING / "A06"

# ── защита: мы там, где надо? ──
if not TRADING.exists():
    print(f"❌ Не нашёл {TRADING}")
    print("   Запусти патч из корня репозитория (где папка studio/).")
    raise SystemExit(1)

(A06 / "forge" / "knowledge").mkdir(parents=True, exist_ok=True)

FILES = {
    TRADING / "brut_live.py":                          '',
    A06 / "forge" / "prompt.md":                       '',
    A06 / "forge" / "knowledge" / "KOTIN_PHILOSOPHY.md": '',
}

stamp = datetime.now().strftime("%Y%m%d_%H%M%S")

for path, b64 in FILES.items():
    content = base64.b64decode(b64)
    if path.exists():
        bak = path.with_suffix(path.suffix + f".bak_{stamp}")
        shutil.copy2(path, bak)
        print(f"💾 бэкап: {bak.name}")
    path.write_bytes(content)
    print(f"✅ {path.relative_to(ROOT)}  ({len(content)} байт)")

# ── проверка маркера ──
brut_path = TRADING / "brut_live.py"
if "BRUT_ENGINE_V1" in brut_path.read_text(encoding="utf-8"):
    print("\n🎯 Маркер BRUT_ENGINE_V1 на месте — мозг Брута лёг.")
else:
    print("\n⚠️  Маркер не найден — проверь файл вручную.")

print("""
─────────────────────────────────────────────
БРУТ РОДИЛСЯ. Проверка руками (нужен MT5 + накрытый стол):

  # сначала накрой стол — прогони сенсоров кнопкой РЫНОК в /exchange,
  # либо вручную run_iskra() → run_morj() → ... → run_arkhiv()
  from studio.modules.trading.brut_live import run_brut
  r = run_brut(symbol="XAUUSD", timeframe="H4")
  print(r["narrative"])      # голос Брута
  print(r["signal"])         # вердикт + цены (если вошёл)
  print(r["diary_entry"])    # что записал в дневник

Дневник копится: studio/modules/trading/state/diary_brut.jsonl
Табло для 09:   trading_state["brut"]

Следующий патч (2): врезка Брута в кнопку РЫНОК + приборы в панель.
─────────────────────────────────────────────
""")
